INSERT INTO public.courses (id, name, description, created, updated) VALUES (2, 'JavaScript', 'Курс JavaScript призначений для вивчення основ однієї з найпопулярніших мов програмування, яка широко використовується у веброзробці. Під час курсу студенти ознайомляться із синтаксисом JavaScript, змінними, типами даних, умовними конструкціями, циклами, функціями, масивами та об''єктами. Отримані знання дозволять створювати власні програми та стануть основою для подальшого вивчення frontend-розробки.', '2026-08-15 14:42:10.684000', null);
INSERT INTO public.courses (id, name, description, created, updated) VALUES (1, 'Python', 'Курс Python знайомить студентів з основами програмування за допомогою простої та зрозумілої мови Python. У процесі навчання студенти опанують змінні, типи даних, умовні конструкції, цикли, функції та основні структури даних. Курс формує базові навички написання програм і створює основу для подальшого вивчення backend-розробки, автоматизації, аналізу даних та інших напрямів.', '2026-08-15 14:41:59.757000', null);
